package com.esn.smp.gameplay;
import com.esn.smp.data.ESNDataStore;
import org.bukkit.*;import org.bukkit.block.*;import org.bukkit.command.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;import org.bukkit.plugin.java.JavaPlugin;
import java.io.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;

public final class CommunitySystems implements Listener,CommandExecutor{
 private final JavaPlugin p;private final ESNDataStore eco;private final File file;private final YamlConfiguration db;private final NamespacedKey backpackKey,stallOwnerKey;private final Map<UUID,String> openBackpacks=new HashMap<>();private final Map<UUID,Integer> openBackpackPages=new HashMap<>();private static final int BACKPACK_SLOTS=248,BACKPACK_PAGE_DATA=45,BACKPACK_PAGES=6;
 public CommunitySystems(JavaPlugin p,ESNDataStore eco){this.p=p;this.eco=eco;file=new File(p.getDataFolder(),"community-systems.yml");db=YamlConfiguration.loadConfiguration(file);backpackKey=new NamespacedKey(p,"backpack_id");stallOwnerKey=new NamespacedKey(p,"stall_owner");}
 private void save(){try{db.save(file);}catch(Exception e){p.getLogger().severe("Community systems save failed: "+e.getMessage());}}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){String n=c.getName();if(n.equals("blackmarket")){if(!(s instanceof Player x)){s.sendMessage("Players only.");return true;}blackMarket(x);return true;}if(n.equals("backpack")){if(!(s instanceof Player x)){s.sendMessage("Players only.");return true;}backpack(x);return true;}if(n.equals("stall")){if(!(s instanceof Player x)){s.sendMessage("Players only.");return true;}stall(x,a);return true;}if(n.equals("bunker")){if(!(s instanceof Player x)){s.sendMessage("Players only.");return true;}bunker(x);return true;}return true;}
 private void stall(Player x,String[] a){String base="stalls."+x.getUniqueId();if(a.length==0){x.sendMessage(ChatColor.GOLD+"Marketplace Stall "+ChatColor.GRAY+"| /stall browse | /stall rent | /stall setprice <coins> | /stall close");if(db.contains(base+".item"))x.sendMessage(ChatColor.YELLOW+"Listed: "+db.getItemStack(base+".item").getType()+" for "+db.getLong(base+".price")+" coins");return;}if(a[0].equalsIgnoreCase("browse")){Inventory v=Bukkit.createInventory(null,54,ChatColor.GOLD+"ESN Marketplace");int slot=0;for(String id:db.getConfigurationSection("stalls")==null?Set.<String>of():db.getConfigurationSection("stalls").getKeys(false)){ItemStack listed=db.getItemStack("stalls."+id+".item");if(listed==null)continue;ItemStack show=listed.clone();ItemMeta sm=show.getItemMeta();List<String> lore=sm.hasLore()?new ArrayList<>(sm.getLore()):new ArrayList<>();lore.add(ChatColor.YELLOW+"Price: "+db.getLong("stalls."+id+".price")+" coins");lore.add(ChatColor.GRAY+"Click to buy");sm.setLore(lore);sm.getPersistentDataContainer().set(stallOwnerKey,PersistentDataType.STRING,id);show.setItemMeta(sm);v.setItem(slot++,show);if(slot>=54)break;}x.openInventory(v);return;}if(a[0].equalsIgnoreCase("rent")){if(db.getBoolean(base+".active")){x.sendMessage(ChatColor.YELLOW+"You already rent a stall.");return;}try{if(!eco.withdraw(x,500)){x.sendMessage(ChatColor.RED+"A stall costs 500 coins.");return;}}catch(Exception e){x.sendMessage(ChatColor.RED+"Economy unavailable.");return;}db.set(base+".active",true);save();x.sendMessage(ChatColor.GREEN+"Marketplace stall rented. Hold an item and use /stall setprice <coins>.");return;}if(a[0].equalsIgnoreCase("close")){ItemStack old=db.getItemStack(base+".item");if(old!=null)x.getInventory().addItem(old).values().forEach(z->x.getWorld().dropItemNaturally(x.getLocation(),z));db.set(base,null);save();x.sendMessage(ChatColor.YELLOW+"Stall closed and stock returned.");return;}if(a[0].equalsIgnoreCase("setprice")&&a.length>1&&db.getBoolean(base+".active")){long price;try{price=Long.parseLong(a[1]);}catch(Exception e){x.sendMessage(ChatColor.RED+"Invalid price.");return;}if(price<1||price>1000000000L){x.sendMessage(ChatColor.RED+"Price must be 1-1,000,000,000.");return;}ItemStack hand=x.getInventory().getItemInMainHand();if(hand.getType().isAir()){x.sendMessage(ChatColor.RED+"Hold the item/stack you want to sell.");return;}ItemStack old=db.getItemStack(base+".item");if(old!=null){x.sendMessage(ChatColor.RED+"Close your existing listing first.");return;}db.set(base+".item",hand.clone());db.set(base+".price",price);x.getInventory().setItemInMainHand(null);save();x.sendMessage(ChatColor.GREEN+"Stall stock listed for "+price+" coins.");return;}x.sendMessage(ChatColor.RED+"Use /stall rent, /stall setprice <coins>, or /stall close.");}
 private void blackMarket(Player x){Inventory v=Bukkit.createInventory(null,27,ChatColor.DARK_PURPLE+"ESN Black Market");v.setItem(11,item(Material.ENDER_PEARL,ChatColor.LIGHT_PURPLE+"Void Bundle",ChatColor.GRAY+"2,500 coins"));v.setItem(13,item(Material.TRIAL_KEY,ChatColor.GOLD+"Contraband Key",ChatColor.GRAY+"7,500 coins"));v.setItem(15,item(Material.NETHERITE_UPGRADE_SMITHING_TEMPLATE,ChatColor.RED+"Forbidden Template",ChatColor.GRAY+"25,000 coins"));x.openInventory(v);}
 private void backpack(Player x){String id="player-"+x.getUniqueId();openBackpackPage(x,id,0);}
 private void openBackpackPage(Player x,String id,int page){page=Math.max(0,Math.min(BACKPACK_PAGES-1,page));Inventory v=Bukkit.createInventory(null,54,ChatColor.DARK_AQUA+"ESN Backpack "+(page+1)+"/"+BACKPACK_PAGES);List<?> list=db.getList("backpacks."+id);int base=page*BACKPACK_PAGE_DATA;for(int i=0;i<BACKPACK_PAGE_DATA&&base+i<BACKPACK_SLOTS;i++)if(list!=null&&base+i<list.size()&&list.get(base+i) instanceof ItemStack it)v.setItem(i,it);for(int i=45;i<54;i++)v.setItem(i,item(Material.GRAY_STAINED_GLASS_PANE," ",ChatColor.GRAY+"Backpack controls"));if(page>0)v.setItem(45,item(Material.ARROW,ChatColor.YELLOW+"Previous Page",ChatColor.GRAY+"Page "+page));if(page<BACKPACK_PAGES-1)v.setItem(53,item(Material.ARROW,ChatColor.YELLOW+"Next Page",ChatColor.GRAY+"Page "+(page+2)));v.setItem(49,item(Material.BUNDLE,ChatColor.GOLD+"Persistent Backpack",ChatColor.GRAY+"248 storage slots",ChatColor.GRAY+"Saved automatically"));openBackpacks.put(x.getUniqueId(),id);openBackpackPages.put(x.getUniqueId(),page);x.openInventory(v);}
 private void saveBackpackPage(Player x,Inventory inv){String id=openBackpacks.get(x.getUniqueId());Integer page=openBackpackPages.get(x.getUniqueId());if(id==null||page==null)return;List<ItemStack> all=new ArrayList<>(Collections.nCopies(BACKPACK_SLOTS,null));List<?> old=db.getList("backpacks."+id);if(old!=null)for(int i=0;i<Math.min(BACKPACK_SLOTS,old.size());i++)if(old.get(i) instanceof ItemStack it)all.set(i,it);int base=page*BACKPACK_PAGE_DATA;for(int i=0;i<BACKPACK_PAGE_DATA&&base+i<BACKPACK_SLOTS;i++)all.set(base+i,inv.getItem(i));db.set("backpacks."+id,all);save();}
 private void bunker(Player x){if(!x.hasPermission("esnsmp.admin")){x.sendMessage(ChatColor.RED+"Admin only.");return;}Location c=x.getLocation().getBlock().getLocation().add(0,-8,0);World w=c.getWorld();for(int dx=-7;dx<=7;dx++)for(int dy=0;dy<=6;dy++)for(int dz=-10;dz<=10;dz++){boolean shell=Math.abs(dx)==7||dy==0||dy==6||Math.abs(dz)==10;w.getBlockAt(c.clone().add(dx,dy,dz)).setType(shell?Material.DEEPSLATE_BRICKS:Material.AIR,false);}for(int z=-8;z<=8;z+=4){w.getBlockAt(c.clone().add(-5,1,z)).setType(Material.REDSTONE_LAMP,false);w.getBlockAt(c.clone().add(5,1,z)).setType(Material.REDSTONE_LAMP,false);}w.getBlockAt(c.clone().add(0,1,9)).setType(Material.IRON_DOOR,false);w.getBlockAt(c.clone().add(-4,1,-7)).setType(Material.BARREL,false);w.getBlockAt(c.clone().add(4,1,-7)).setType(Material.BARREL,false);x.sendMessage(ChatColor.GREEN+"Secret bunker generated beneath you at Y "+c.getBlockY()+".");}
 private ItemStack item(Material mat,String name,String... lore){ItemStack i=new ItemStack(mat);ItemMeta m=i.getItemMeta();m.setDisplayName(name);m.setLore(List.of(lore));i.setItemMeta(m);return i;}
 @EventHandler public void click(InventoryClickEvent e){if(e.getView().getTitle().startsWith(ChatColor.DARK_AQUA+"ESN Backpack ")){if(!(e.getWhoClicked() instanceof Player x))return;if(e.getRawSlot()>=45&&e.getRawSlot()<54){e.setCancelled(true);if(e.getRawSlot()==45&&openBackpackPages.getOrDefault(x.getUniqueId(),0)>0){int next=openBackpackPages.get(x.getUniqueId())-1;saveBackpackPage(x,e.getInventory());openBackpackPage(x,openBackpacks.get(x.getUniqueId()),next);}else if(e.getRawSlot()==53&&openBackpackPages.getOrDefault(x.getUniqueId(),0)<BACKPACK_PAGES-1){int next=openBackpackPages.get(x.getUniqueId())+1;saveBackpackPage(x,e.getInventory());openBackpackPage(x,openBackpacks.get(x.getUniqueId()),next);}return;}return;}if(e.getView().getTitle().equals(ChatColor.GOLD+"ESN Marketplace")){e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player buyer)||e.getCurrentItem()==null)return;ItemMeta meta=e.getCurrentItem().getItemMeta();String owner=meta==null?null:meta.getPersistentDataContainer().get(stallOwnerKey,PersistentDataType.STRING);if(owner==null)return;String base="stalls."+owner;ItemStack stock=db.getItemStack(base+".item");long price=db.getLong(base+".price");if(stock==null)return;Player seller;try{seller=Bukkit.getPlayer(UUID.fromString(owner));}catch(Exception ex){return;}if(seller==null){buyer.sendMessage(ChatColor.RED+"That seller must be online to complete this purchase.");return;}try{if(!eco.withdraw(buyer,price)){buyer.sendMessage(ChatColor.RED+"Not enough coins.");return;}eco.deposit(seller,price);}catch(Exception ex){buyer.sendMessage(ChatColor.RED+"Economy unavailable.");return;}buyer.getInventory().addItem(stock).values().forEach(z->buyer.getWorld().dropItemNaturally(buyer.getLocation(),z));db.set(base+".item",null);save();buyer.closeInventory();buyer.sendMessage(ChatColor.GREEN+"Marketplace purchase complete.");seller.sendMessage(ChatColor.GREEN+"Your marketplace item sold for "+price+" coins.");return;}if(!e.getView().getTitle().equals(ChatColor.DARK_PURPLE+"ESN Black Market"))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player x)||e.getCurrentItem()==null)return;int slot=e.getRawSlot();long price=slot==11?2500:slot==13?7500:slot==15?25000:0;if(price==0)return;try{if(!eco.withdraw(x,price)){x.sendMessage(ChatColor.RED+"Not enough coins.");return;}}catch(Exception ex){x.sendMessage(ChatColor.RED+"Economy unavailable.");return;}ItemStack reward=slot==11?new ItemStack(Material.ENDER_PEARL,8):slot==13?new ItemStack(Material.TRIAL_KEY):new ItemStack(Material.NETHERITE_UPGRADE_SMITHING_TEMPLATE);x.getInventory().addItem(reward).values().forEach(z->x.getWorld().dropItemNaturally(x.getLocation(),z));x.sendMessage(ChatColor.GREEN+"Black Market purchase complete.");}
 @EventHandler public void close(org.bukkit.event.inventory.InventoryCloseEvent e){if(!e.getView().getTitle().startsWith(ChatColor.DARK_AQUA+"ESN Backpack "))return;Player x=(Player)e.getPlayer();saveBackpackPage(x,e.getInventory());openBackpacks.remove(x.getUniqueId());openBackpackPages.remove(x.getUniqueId());}
}